export const LANDING_CSS = "\n/* Layout: a product page that shows the product. Wide hero split (thesis | tool composer),\n   then full-width bands: live gateway log, sub-agent tree, three-step path, connect tabs. */\n:root {\n  color-scheme: light;\n  --paper: #f5f7f4;        /* page, faint green bias */\n  --surface: #ffffff;\n  --sunk: #edf1ec;         /* recessed panels, code chips */\n  --ink: #0f1a14;          /* text */\n  --muted: #56645b;        /* secondary text */\n  --line: #d9e1da;         /* hairlines */\n  --accent: #16784f;       /* signal green: the gateway's \"checked\" color */\n  --accent-soft: #e3f3ea;\n  --code-bg: #0f1a14;\n  --code-ink: #e6efe8;\n  --allow: #15803d;  --allow-soft: #e6f6ea;\n  --hold: #b45309;   --hold-soft: #fdf1e2;\n  --block: #c2261d;  --block-soft: #fde9e7;\n  --taint: #7c3aed;  --taint-soft: #f1eafe;\n  --glow: rgba(22,120,79,.16);\n  --f-display: \"Bricolage Grotesque\", \"Segoe UI\", system-ui, sans-serif;\n  --f-body: \"IBM Plex Sans\", \"Segoe UI\", system-ui, sans-serif;\n  --f-mono: \"JetBrains Mono\", ui-monospace, \"SFMono-Regular\", Menlo, monospace;\n  --r: 14px;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    color-scheme: dark;\n    --paper: #0b110e; --surface: #121a16; --sunk: #18221d; --ink: #e8efe9; --muted: #98a89e; --line: #26332c;\n    --accent: #4ccb8f; --accent-soft: #143024; --code-bg: #060a08; --code-ink: #d9e8de;\n    --allow: #4ade80; --allow-soft: #12301f; --hold: #fbbf24; --hold-soft: #33260f;\n    --block: #f87171; --block-soft: #3a1513; --taint: #c4a5ff; --taint-soft: #261a3d; --glow: rgba(76,203,143,.14);\n  }\n}\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n  --paper: #0b110e; --surface: #121a16; --sunk: #18221d; --ink: #e8efe9; --muted: #98a89e; --line: #26332c;\n  --accent: #4ccb8f; --accent-soft: #143024; --code-bg: #060a08; --code-ink: #d9e8de;\n  --allow: #4ade80; --allow-soft: #12301f; --hold: #fbbf24; --hold-soft: #33260f;\n  --block: #f87171; --block-soft: #3a1513; --taint: #c4a5ff; --taint-soft: #261a3d; --glow: rgba(76,203,143,.14);\n}\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  margin: 0; background: var(--paper); color: var(--ink);\n  font: 16px/1.6 var(--f-body);\n  padding-left: max(16px, env(safe-area-inset-left, 0px));\n  padding-right: max(16px, env(safe-area-inset-right, 0px));\n}\nbody::before { content: \"\"; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--paper); }\na { color: inherit; }\nbutton { font: inherit; color: inherit; cursor: pointer; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }\n.wrap { max-width: 1180px; margin: 0 auto; }\nh1, h2, h3 { font-family: var(--f-display); text-wrap: balance; margin: 0; letter-spacing: -0.02em; }\np { margin: 0; }\n.mono { font-family: var(--f-mono); }\n.eyebrow { font: 500 12px/1 var(--f-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--accent); }\n.lede { color: var(--muted); font-size: 18px; max-width: 58ch; }\n.btn { display: inline-flex; align-items: center; gap: 8px; border-radius: 10px; padding: 11px 18px; font-weight: 600; font-size: 15px; text-decoration: none; border: 1px solid var(--line); background: var(--surface); transition: transform .15s, background .15s; }\n.btn:hover { transform: translateY(-1px); }\n.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--paper); }\n.btn.small { padding: 6px 11px; font-size: 13px; border-radius: 8px; }\n\n/* ---------- nav ---------- */\nnav.top { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; background: color-mix(in srgb, var(--paper) 86%, transparent); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); margin: 0 calc(-1 * max(16px, env(safe-area-inset-left, 0px))); padding: 0 max(16px, env(safe-area-inset-left, 0px)); }\nnav.top .wrap { display: flex; align-items: center; gap: 28px; height: 64px; }\n.brand { display: flex; align-items: center; gap: 10px; font: 700 18px var(--f-display); text-decoration: none; }\n.navlinks { display: flex; gap: 22px; font-size: 14px; color: var(--muted); }\n.navlinks a { text-decoration: none; }\n.navlinks a:hover { color: var(--ink); }\n.navend { margin-left: auto; display: flex; gap: 10px; align-items: center; }\n.themebtn { border: 1px solid var(--line); background: var(--surface); border-radius: 8px; width: 36px; height: 36px; display: grid; place-items: center; }\n@media (max-width: 860px) { .navlinks { display: none; } }\n\n/* ---------- hero ---------- */\n.hero { display: grid; grid-template-columns: 1fr 1.05fr; gap: 56px; padding-block: 72px 56px; align-items: center; }\n.hero h1 { font-size: clamp(40px, 5.6vw, 68px); line-height: 1.02; font-weight: 800; }\n.hero h1 em { font-style: normal; color: var(--accent); }\n.hero .lede { margin-top: 22px; }\n.hero .ctas { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }\n.proof { margin-top: 30px; display: flex; flex-wrap: wrap; gap: 8px 18px; font: 12px var(--f-mono); color: var(--muted); }\n.proof span::before { content: \"\u2713 \"; color: var(--accent); }\n@media (max-width: 960px) { .hero { grid-template-columns: 1fr; padding-block: 40px; gap: 36px; } }\n\n/* composer (tool catalogs -> one agent's allowed tools -> endpoint) */\n.composer { position: relative; }\n.ups { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }\n.up { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); padding: 12px; min-width: 0; }\n.up-head { display: flex; align-items: center; gap: 8px; }\n.up-icon { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: var(--sunk); flex: none; }\n.up-name { font: 700 11px var(--f-mono); letter-spacing: .08em; text-transform: uppercase; }\n.up-count { font: 11px var(--f-mono); color: var(--muted); }\n.tools { display: grid; gap: 6px; margin-top: 10px; }\n.tool { display: flex; align-items: center; gap: 7px; border: 1px solid var(--line); border-radius: 8px; padding: 5px 7px; font: 11px var(--f-mono); background: var(--surface); text-align: left; width: 100%; min-width: 0; }\n.tool .box { width: 14px; height: 14px; border-radius: 4px; border: 1.5px solid var(--line); flex: none; display: grid; place-items: center; }\n.tool .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.tool[aria-pressed=\"true\"] { background: var(--accent-soft); border-color: color-mix(in srgb, var(--accent) 40%, var(--line)); }\n.tool[aria-pressed=\"true\"] .box { background: var(--accent); border-color: var(--accent); }\n.tool[aria-pressed=\"true\"] .box::after { content: \"\"; width: 7px; height: 4px; border: 2px solid var(--paper); border-top: 0; border-right: 0; transform: rotate(-45deg) translate(1px,-1px); }\n.more { margin-top: 8px; font: 600 11px var(--f-mono); color: var(--accent); background: none; border: 0; padding: 0; letter-spacing: .04em; }\n.wires { display: block; width: 100%; height: 56px; }\n.wires path { fill: none; stroke: var(--accent); stroke-width: 1.6; opacity: .55; }\n.agent { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); padding: 16px; box-shadow: 0 18px 50px -24px var(--glow); }\n.agent-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }\n.agent-name { font: 700 15px var(--f-mono); letter-spacing: .02em; }\n.agent-count { font: 500 12px var(--f-mono); color: var(--accent); }\n.agent-count::before { content: \"\u25cf \"; }\n.picked { display: grid; gap: 6px; margin-top: 12px; max-height: 236px; overflow: auto; }\n.pick { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; font: 13px var(--f-mono); background: var(--sunk); }\n.pick .nm { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.chip { font: 600 10px var(--f-mono); letter-spacing: .06em; text-transform: uppercase; padding: 3px 7px; border-radius: 99px; white-space: nowrap; }\n.chip.read { background: var(--accent-soft); color: var(--accent); }\n.chip.write { background: var(--taint-soft); color: var(--taint); }\n.chip.money { background: var(--hold-soft); color: var(--hold); }\n.chip.never { background: var(--block-soft); color: var(--block); }\n.endpoint { margin-top: 14px; display: flex; align-items: center; gap: 10px; background: var(--code-bg); color: var(--code-ink); border-radius: 12px; padding: 12px 14px; font: 13px var(--f-mono); overflow-x: auto; white-space: nowrap; }\n.endpoint b { color: #7ee2ae; font-weight: 500; }\n.empty-pick { font-size: 13px; color: var(--muted); padding: 10px; border: 1px dashed var(--line); border-radius: 9px; }\n@media (max-width: 640px) { .ups { grid-template-columns: repeat(2, 1fr); } }\n\n/* ---------- bands ---------- */\nsection.band { padding-block: 88px; border-top: 1px solid var(--line); }\n.band-head { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: end; margin-bottom: 36px; }\n.band-head h2 { font-size: clamp(32px, 4.2vw, 50px); line-height: 1.04; font-weight: 800; }\n.band-head h2 em { font-style: normal; color: var(--accent); }\n@media (max-width: 860px) { .band-head { grid-template-columns: 1fr; gap: 14px; } section.band { padding-block: 56px; } }\n\n/* simulator */\n.sim { display: grid; grid-template-columns: 320px 1fr; gap: 20px; align-items: start; }\n@media (max-width: 960px) { .sim { grid-template-columns: 1fr; } }\n.panel { background: var(--surface); border: 1px solid var(--line); border-radius: var(--r); }\n.controls { padding: 18px; display: grid; gap: 16px; }\n.ctl-title { font: 600 12px var(--f-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }\n.acts { display: grid; gap: 8px; }\n.act { display: grid; grid-template-columns: 1fr auto; gap: 2px 10px; align-items: center; text-align: left; border: 1px solid var(--line); background: var(--surface); border-radius: 10px; padding: 10px 12px; transition: border-color .15s, background .15s; }\n.act:hover { border-color: var(--accent); background: var(--accent-soft); }\n.act:disabled { opacity: .5; cursor: not-allowed; }\n.act b { font-size: 14px; font-weight: 600; }\n.act small { grid-column: 1; color: var(--muted); font: 11px var(--f-mono); }\n.act .risk { grid-row: 1 / span 2; grid-column: 2; font: 600 11px var(--f-mono); }\n.state { display: grid; gap: 8px; font-size: 13px; }\n.state-row { display: flex; justify-content: space-between; gap: 10px; align-items: center; }\n.state-row span:first-child { color: var(--muted); }\n.pill { display: inline-flex; align-items: center; gap: 6px; font: 600 11px var(--f-mono); letter-spacing: .04em; padding: 4px 9px; border-radius: 99px; white-space: nowrap; border: 1px solid transparent; }\n.pill.ok { background: var(--allow-soft); color: var(--allow); border-color: color-mix(in srgb, var(--allow) 30%, transparent); }\n.pill.hold { background: var(--hold-soft); color: var(--hold); border-color: color-mix(in srgb, var(--hold) 30%, transparent); }\n.pill.bad { background: var(--block-soft); color: var(--block); border-color: color-mix(in srgb, var(--block) 30%, transparent); }\n.pill.taint { background: var(--taint-soft); color: var(--taint); border-color: color-mix(in srgb, var(--taint) 30%, transparent); }\n.log-head { display: flex; justify-content: space-between; align-items: center; padding: 14px 18px; border-bottom: 1px solid var(--line); }\n.log-head .t { font: 600 13px var(--f-mono); letter-spacing: .1em; }\n.live { font: 600 11px var(--f-mono); color: var(--accent); letter-spacing: .08em; }\n.live::before { content: \"\u25cf\"; margin-right: 6px; animation: pulse 1.6s infinite; }\n@keyframes pulse { 50% { opacity: .25; } }\n.log { list-style: none; margin: 0; padding: 10px; display: grid; gap: 8px; max-height: 520px; overflow: auto; }\n.row { display: grid; grid-template-columns: 36px 1fr auto; gap: 12px; align-items: center; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); animation: slide .35s ease-out; }\n.row.v-allow { border-color: color-mix(in srgb, var(--allow) 28%, var(--line)); }\n.row.v-hold { border-color: color-mix(in srgb, var(--hold) 45%, var(--line)); background: color-mix(in srgb, var(--hold-soft) 50%, var(--surface)); }\n.row.v-block { border-color: color-mix(in srgb, var(--block) 40%, var(--line)); }\n@keyframes slide { from { transform: translateY(-6px); opacity: .4; } }\n.ricon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: var(--sunk); }\n.rtool { font: 600 14px var(--f-mono); overflow-wrap: anywhere; }\n.rmeta { font: 12px var(--f-mono); color: var(--muted); overflow-wrap: anywhere; }\n.rwhy { font-size: 12.5px; color: var(--muted); margin-top: 4px; }\n.rwhy.taint { color: var(--taint); }\n.approve { grid-column: 2 / -1; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; padding-top: 4px; }\n.approve .q { font-size: 13px; margin-right: 4px; }\n.features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 44px; }\n.feature h3 { font-size: 20px; margin: 14px 0 6px; font-weight: 700; }\n.feature p { color: var(--muted); font-size: 15px; }\n.ficon { width: 44px; height: 44px; border: 1px solid var(--line); border-radius: 12px; display: grid; place-items: center; background: var(--surface); }\n@media (max-width: 760px) { .features { grid-template-columns: 1fr; } }\n\n/* sub-agent tree */\n.subgrid { display: grid; grid-template-columns: 1.2fr .8fr; gap: 20px; align-items: start; }\n@media (max-width: 960px) { .subgrid { grid-template-columns: 1fr; } }\n.tree { padding: 22px; }\n.node { display: grid; grid-template-columns: 40px 1fr auto; gap: 12px; align-items: center; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }\n.node.parent { border-color: color-mix(in srgb, var(--accent) 40%, var(--line)); }\n.node.dead { opacity: .55; }\n.node.dead .nname { text-decoration: line-through; }\n.avatar { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; font: 700 13px var(--f-mono); background: var(--accent-soft); color: var(--accent); }\n.nname { font: 600 14px var(--f-mono); overflow-wrap: anywhere; }\n.nmeta { font-size: 12.5px; color: var(--muted); display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 3px; }\n.clock { font: 600 12px var(--f-mono); font-variant-numeric: tabular-nums; }\n.children { margin: 10px 0 0 19px; padding-left: 28px; border-left: 1.5px dashed color-mix(in srgb, var(--accent) 45%, var(--line)); display: grid; gap: 10px; }\n.children .node { position: relative; }\n.children .node::before { content: \"\"; position: absolute; left: -29px; top: 50%; width: 27px; border-top: 1.5px dashed color-mix(in srgb, var(--accent) 45%, var(--line)); }\n.tree-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }\n.spawn { padding: 20px; display: grid; gap: 14px; }\n.spawn h3 { font-size: 20px; }\n.field label { display: block; font: 600 12px var(--f-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin-bottom: 6px; }\n.field input[type=text] { width: 100%; border: 1px solid var(--line); background: var(--paper); color: var(--ink); border-radius: 9px; padding: 9px 11px; font: 14px var(--f-mono); }\n.seg { display: flex; gap: 6px; flex-wrap: wrap; }\n.seg button { border: 1px solid var(--line); background: var(--surface); border-radius: 8px; padding: 7px 12px; font: 600 13px var(--f-mono); }\n.seg button[aria-pressed=\"true\"] { background: var(--accent); color: var(--paper); border-color: var(--accent); }\n.perm { display: flex; align-items: center; gap: 10px; font-size: 14px; padding: 6px 0; }\n.perm input { accent-color: var(--accent); width: 16px; height: 16px; }\n.perm.off { color: var(--muted); }\n.note { font-size: 13px; color: var(--muted); }\n\n/* path */\n.path { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; counter-reset: step; }\n.stepc { padding: 22px; position: relative; }\n.stepc .n { font: 700 12px var(--f-mono); color: var(--accent); letter-spacing: .1em; }\n.stepc h3 { font-size: 22px; margin: 10px 0 8px; }\n.stepc p { color: var(--muted); font-size: 15px; }\n.stepc .specs { margin-top: 14px; display: flex; flex-wrap: wrap; gap: 6px; }\n.spec { font: 11px var(--f-mono); padding: 3px 8px; border-radius: 6px; background: var(--sunk); color: var(--muted); }\n@media (max-width: 860px) { .path { grid-template-columns: 1fr; } }\n\n/* connect */\n.tabs { display: flex; gap: 6px; flex-wrap: wrap; padding: 10px; border-bottom: 1px solid var(--line); }\n.tab { border: 1px solid transparent; background: none; border-radius: 9px; padding: 8px 14px; font-weight: 600; font-size: 14px; color: var(--muted); }\n.tab[aria-selected=\"true\"] { background: var(--sunk); color: var(--ink); border-color: var(--line); }\n.tabpanel { padding: 20px; display: grid; gap: 14px; }\n.tabpanel ol { margin: 0; padding-left: 20px; display: grid; gap: 14px; color: var(--muted); font-size: 15px; }\n.tabpanel li > span { color: var(--ink); }\n.code { position: relative; background: var(--code-bg); color: var(--code-ink); border-radius: 12px; padding: 14px 70px 14px 16px; font: 13px/1.6 var(--f-mono); white-space: pre-wrap; overflow-wrap: anywhere; margin-top: 8px; }\n.copy { position: absolute; top: 10px; right: 10px; background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.14); color: var(--code-ink); border-radius: 7px; padding: 4px 10px; font: 600 11px var(--f-mono); }\n\n/* standards + cta + footer */\n.stds { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 28px; }\n.std { border: 1px solid var(--line); background: var(--surface); border-radius: 10px; padding: 10px 14px; display: grid; gap: 2px; }\n.std b { font: 600 13px var(--f-mono); }\n.std span { font-size: 12.5px; color: var(--muted); }\n.cta { margin-block: 88px 40px; background: var(--code-bg); color: var(--code-ink); border-radius: 24px; padding: 56px max(24px, 5vw); display: grid; grid-template-columns: 1.3fr 1fr; gap: 32px; align-items: center; }\n.cta h2 { font-size: clamp(30px, 4vw, 48px); font-weight: 800; line-height: 1.05; color: #f1f7f3; }\n.cta p { color: #a9bdb0; margin-top: 12px; }\n.cta .btns { display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end; }\n.cta .btn { background: transparent; color: #f1f7f3; border-color: rgba(255,255,255,.2); }\n.cta .btn.primary { background: #4ccb8f; color: #06110b; border-color: #4ccb8f; }\n@media (max-width: 860px) { .cta { grid-template-columns: 1fr; } .cta .btns { justify-content: flex-start; } }\nfooter { padding-block: 28px 48px; color: var(--muted); font-size: 13px; display: flex; flex-wrap: wrap; gap: 12px 28px; justify-content: space-between; border-top: 1px solid var(--line); }\n.toast { position: fixed; left: 50%; bottom: max(20px, env(safe-area-inset-bottom, 0px)); transform: translate(-50%, 16px); opacity: 0; visibility: hidden; background: var(--ink); color: var(--paper); padding: 10px 16px; border-radius: 10px; font-size: 14px; transition: transform .25s, opacity .25s, visibility .25s; z-index: 40; }\n.toast.show { transform: translate(-50%, 0); opacity: 1; visibility: visible; }\n/* grid children may shrink below their content; long rows wrap instead of widening the page */\n.hero > *, .sim > *, .subgrid > *, .band-head > *, .path > *, .cta > * { min-width: 0; }\n@media (max-width: 560px) {\n  .row { grid-template-columns: 36px 1fr; }\n  .row > .pill { grid-column: 2; justify-self: start; }\n  .approve { grid-column: 1 / -1; }\n  .node { grid-template-columns: 40px 1fr; }\n  .node > .clock { grid-column: 2; }\n  .endpoint span:last-child { display: none; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before { animation: none !important; transition: none !important; } html { scroll-behavior: auto; } }\n";

export const LANDING_HTML = "\n\n<nav class=\"top\" aria-label=\"Main\">\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Agent Identity home\">\n      <svg width=\"28\" height=\"28\" viewBox=\"0 0 28 28\" aria-hidden=\"true\"><path d=\"M14 2.5 24 6.5v7c0 6.2-4.2 10.6-10 12-5.8-1.4-10-5.8-10-12v-7z\" fill=\"var(--accent)\"/><path d=\"M9.5 14.2l3.1 3.1 6-6.3\" fill=\"none\" stroke=\"var(--paper)\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n      Agent Identity\n    </a>\n    <div class=\"navlinks\">\n      <a href=\"#gateway\">Gateway</a><a href=\"#subagents\">Sub-agents</a><a href=\"#how\">How it works</a><a href=\"#connect\">Connect</a>\n    </div>\n    <div class=\"navend\">\n      <button class=\"themebtn\" id=\"themeBtn\" type=\"button\" aria-label=\"Switch light or dark theme\" title=\"Switch theme\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"M8 1.5a6.5 6.5 0 1 0 0 13z\" fill=\"currentColor\"/><circle cx=\"8\" cy=\"8\" r=\"6.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/></svg>\n      </button>\n      <a class=\"btn small\" href=\"#signin\" data-signin>Sign in</a>\n    </div>\n  </div>\n</nav>\n\n<main class=\"wrap\" id=\"top\">\n  <!-- HERO -->\n  <section class=\"hero\">\n    <div>\n      <div class=\"eyebrow\">Identity and runtime authorization for AI agents</div>\n      <h1 style=\"margin-top:18px\">Every agent gets an identity. <em>Every tool call gets a decision.</em></h1>\n      <p class=\"lede\">Claude, Gemini and ChatGPT connect to your tools through one gateway. A person approves what each agent may do and for how long. Every call is checked, risky ones wait for a human, and one click cuts an agent and its sub-agents off.</p>\n      <div class=\"ctas\">\n        <a class=\"btn primary\" href=\"#signin\" data-signin>Open the console \u2192</a>\n        <button class=\"btn\" type=\"button\" data-copy=\"claude mcp add --transport http -s user agentid-gateway https://agentid-gateway-301065961025.asia-south1.run.app/mcp\">Copy Claude Code command</button>\n      </div>\n      <div class=\"proof\"><span>OAuth 2.1 + PKCE</span><span>MCP gateway</span><span>Human approvals (CIBA)</span><span>Live on Google Cloud</span></div>\n    </div>\n\n    <div class=\"composer\" aria-label=\"Choose which tools this agent may use\">\n      <div class=\"ups\" id=\"ups\"></div>\n      <svg class=\"wires\" viewBox=\"0 0 400 56\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n        <path d=\"M50 0 C50 34, 200 22, 200 56\"/><path d=\"M150 0 C150 30, 200 26, 200 56\"/><path d=\"M250 0 C250 30, 200 26, 200 56\"/><path d=\"M350 0 C350 34, 200 22, 200 56\"/>\n      </svg>\n      <div class=\"agent\">\n        <div class=\"agent-head\">\n          <span class=\"agent-name\">CLAUDE-CODE \u00b7 FINANCE-OPS</span>\n          <span class=\"agent-count\" id=\"pickCount\">0 of 23 tools</span>\n        </div>\n        <div class=\"picked\" id=\"picked\"></div>\n        <div class=\"endpoint\" aria-label=\"Gateway address\"><span>agentid-gateway\u2026run.app</span><b>/mcp</b><span style=\"margin-left:auto;color:#8fa79a\">\u00b7 consent 1 h \u00b7 approved by priya@acme.in</span></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- GATEWAY SIMULATOR -->\n  <section class=\"band\" id=\"gateway\">\n    <div class=\"band-head\">\n      <h2>See every tool call your agents make. <em>And who allowed it.</em></h2>\n      <p class=\"lede\">Try it: send calls through the gateway as Claude would. Reads pass in milliseconds, a payment waits for you, and a prompt injection followed by data going to an unknown site is blocked and the agent's access revoked.</p>\n    </div>\n    <div class=\"sim\">\n      <div class=\"panel controls\">\n        <div class=\"ctl-title\">Make Claude call</div>\n        <div class=\"acts\" id=\"acts\"></div>\n        <div class=\"ctl-title\" style=\"margin-top:4px\">Agent state</div>\n        <div class=\"state\">\n          <div class=\"state-row\"><span>Access</span><span id=\"stAccess\" class=\"pill ok\">Active \u00b7 read, money \u00b7 1 h</span></div>\n          <div class=\"state-row\"><span>Context</span><span id=\"stCtx\" class=\"pill ok\">Clean</span></div>\n          <div class=\"state-row\"><span>Calls today</span><span class=\"mono\" id=\"stCalls\">0</span></div>\n        </div>\n        <button class=\"btn small\" type=\"button\" id=\"resetSim\">Reconnect and reset</button>\n      </div>\n      <div class=\"panel\">\n        <div class=\"log-head\"><span class=\"t\">TOOL CALL LOG</span><span class=\"live\">STREAMING</span></div>\n        <ol class=\"log\" id=\"log\" aria-live=\"polite\"></ol>\n      </div>\n    </div>\n    <div class=\"features\">\n      <div class=\"feature\">\n        <div class=\"ficon\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"6.5\" r=\"3.2\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><path d=\"M2.5 17c.8-3.4 3-5 5.5-5 1.3 0 2.4.4 3.3 1.1M12.5 15l2 2 3.5-4\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n        <h3>Every call, fully attributed</h3>\n        <p>Agent, sub-agent, user, tool, risk score and decision on every row. Nothing to piece together later from application logs.</p>\n      </div>\n      <div class=\"feature\">\n        <div class=\"ficon\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"14\" height=\"12\" rx=\"2.5\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><path d=\"M7 10h6M10 7v6\" stroke=\"var(--hold)\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg></div>\n        <h3>A person approves the risky ones</h3>\n        <p>Payments and changes outside the grant pause and appear in the console. Allow once, or for 10 minutes or an hour, never beyond the original grant.</p>\n      </div>\n      <div class=\"feature\">\n        <div class=\"ficon\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2.5 17 16H3z\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><path d=\"M10 8v3.5M10 13.6v.1\" stroke=\"var(--block)\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></div>\n        <h3>Injections stop at the gateway</h3>\n        <p>Untrusted text marks the session. After that, sending data to an unknown site is blocked and the agent's tokens are revoked in under a millisecond.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- SUB-AGENTS -->\n  <section class=\"band\" id=\"subagents\">\n    <div class=\"band-head\">\n      <h2>Sub-agents get <em>their own identity</em>, never more than their parent.</h2>\n      <p class=\"lede\">When an agent says \"create an agent and\u2026\", the gateway sees the new sub-agent and asks you once. It gets a subset of the parent's permissions, never payments, for 5 minutes, 10 minutes or an hour. Revoke the parent and every child goes with it.</p>\n    </div>\n    <div class=\"subgrid\">\n      <div class=\"panel tree\">\n        <div id=\"tree\"></div>\n        <div class=\"tree-actions\">\n          <button class=\"btn small\" type=\"button\" id=\"revokeParent\">Revoke Claude Code</button>\n          <button class=\"btn small\" type=\"button\" id=\"resetTree\">Reset</button>\n        </div>\n      </div>\n      <form class=\"panel spawn\" id=\"spawnForm\" aria-label=\"Approve a new sub-agent\">\n        <div class=\"eyebrow\">New sub-agent wants access</div>\n        <h3>Approve a sub-agent</h3>\n        <div class=\"field\"><label for=\"subName\">Name</label><input type=\"text\" id=\"subName\" value=\"invoice-checker\" maxlength=\"24\" autocomplete=\"off\"></div>\n        <div class=\"field\">\n          <label>Allow it to</label>\n          <label class=\"perm\"><input type=\"checkbox\" id=\"pRead\" checked> Read data</label>\n          <label class=\"perm\"><input type=\"checkbox\" id=\"pWrite\"> Change data</label>\n          <label class=\"perm off\"><input type=\"checkbox\" disabled> Move money <span class=\"chip never\" style=\"margin-left:6px\">never for sub-agents</span></label>\n        </div>\n        <div class=\"field\">\n          <label>For</label>\n          <div class=\"seg\" id=\"ttlSeg\" role=\"group\" aria-label=\"How long\">\n            <button type=\"button\" data-ttl=\"300\" aria-pressed=\"false\">5 min</button>\n            <button type=\"button\" data-ttl=\"600\" aria-pressed=\"true\">10 min</button>\n            <button type=\"button\" data-ttl=\"3600\" aria-pressed=\"false\">1 hour</button>\n          </div>\n        </div>\n        <p class=\"note\" id=\"spawnNote\">It works under Claude Code and can't outlive its 52 minutes of access.</p>\n        <button class=\"btn primary\" type=\"submit\">Approve sub-agent</button>\n      </form>\n    </div>\n  </section>\n\n  <!-- HOW IT WORKS -->\n  <section class=\"band\" id=\"how\">\n    <div class=\"band-head\">\n      <h2>Three checks on the path of <em>every request</em>.</h2>\n      <p class=\"lede\">Built on open standards, so any MCP client works without an SDK: no API keys to paste, no custom plugins.</p>\n    </div>\n    <div class=\"path\">\n      <div class=\"panel stepc\">\n        <div class=\"n\">1 \u00b7 SIGN IN</div>\n        <h3>A person consents</h3>\n        <p>The agent registers itself and opens our consent screen. You choose what it may do (read, change, move money) and for how long. It gets a short-lived token bound to that grant.</p>\n        <div class=\"specs\"><span class=\"spec\">OAuth 2.1 + PKCE</span><span class=\"spec\">RFC 7591 DCR</span><span class=\"spec\">Client ID metadata</span><span class=\"spec\">RFC 9396 RAR</span></div>\n      </div>\n      <div class=\"panel stepc\">\n        <div class=\"n\">2 \u00b7 EVERY CALL</div>\n        <h3>The gateway checks it</h3>\n        <p>Your real MCP servers sit behind the gateway. Each tool call is classified (read, write, payment, export, delete) and checked against the grant, the destination and what the agent read before.</p>\n        <div class=\"specs\"><span class=\"spec\">MCP Streamable HTTP</span><span class=\"spec\">RFC 9728</span><span class=\"spec\">RFC 7662</span></div>\n      </div>\n      <div class=\"panel stepc\">\n        <div class=\"n\">3 \u00b7 DECISION</div>\n        <h3>Allow, ask or block</h3>\n        <p>Below 0.30 risk it passes. Up to 0.75 a person approves it. Above that, or on a hard rule such as \"never delete\", it is blocked and the token family revoked, sub-agents included.</p>\n        <div class=\"specs\"><span class=\"spec\">OpenID CIBA</span><span class=\"spec\">RFC 8693 token exchange</span><span class=\"spec\">Cascade revoke</span></div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CONNECT -->\n  <section class=\"band\" id=\"connect\">\n    <div class=\"band-head\">\n      <h2>Connect any agent <em>in one command</em>.</h2>\n      <p class=\"lede\">The gateway speaks standard MCP with OAuth. The client signs in through your consent screen; nothing else to install.</p>\n    </div>\n    <div class=\"panel\">\n      <div class=\"tabs\" role=\"tablist\" aria-label=\"Choose your agent\" id=\"tabs\"></div>\n      <div class=\"tabpanel\" role=\"tabpanel\" id=\"tabpanel\"></div>\n    </div>\n    <div class=\"stds\" aria-label=\"Standards\">\n      <div class=\"std\"><b>OAuth 2.1</b><span>sign-in with PKCE</span></div>\n      <div class=\"std\"><b>MCP</b><span>Streamable HTTP</span></div>\n      <div class=\"std\"><b>RFC 8693</b><span>sub-agent tokens</span></div>\n      <div class=\"std\"><b>RFC 9396</b><span>fine-grained consent</span></div>\n      <div class=\"std\"><b>OpenID CIBA</b><span>human approvals</span></div>\n      <div class=\"std\"><b>RFC 9728</b><span>resource discovery</span></div>\n    </div>\n  </section>\n\n  <section class=\"cta\">\n    <div>\n      <h2>Put your agents behind a gateway you can see.</h2>\n      <p>Create an organization, connect Claude Code or Gemini, and watch every call in the console.</p>\n    </div>\n    <div class=\"btns\">\n      <a class=\"btn primary\" href=\"#signin\" data-signin>Create an organization</a>\n      <a class=\"btn\" href=\"#connect\">See connect steps</a>\n    </div>\n  </section>\n\n  <footer>\n    <span>Agent Identity \u00b7 DeltaWaveX</span>\n    <span class=\"mono\">asia-south1 \u00b7 Cloud Run \u00b7 Cloud SQL</span>\n  </footer>\n</main>\n\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n";

/** Wires up the interactive parts. Returns a cleanup function. */
export function initLanding(onTryNow) {
  const $ = (s, el = document) => el.querySelector(s);
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const toast = msg => { const t = $("#toast"); t.textContent = msg; t.classList.add("show"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove("show"), 2200); };

  // ---------- theme ----------
  $("#themeBtn").addEventListener("click", () => {
    const root = document.documentElement;
    const dark = root.dataset.theme ? root.dataset.theme === "dark" : matchMedia("(prefers-color-scheme: dark)").matches;
    root.dataset.theme = dark ? "light" : "dark";
  });

  // ---------- copy ----------
  const onDocClick = e => {
    const s = e.target.closest("[data-signin]");
    if (s) { e.preventDefault(); onTryNow(); return; }
    const b = e.target.closest("[data-copy]");
    if (!b) return;
    const text = b.dataset.copy;
    (navigator.clipboard?.writeText(text) || Promise.reject()).then(() => toast("Copied"), () => toast("Copy failed: select the text instead"));
  };
  document.addEventListener("click", onDocClick);

  // ---------- icons ----------
  const ICON = {
    bank: '<svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="M2 7 9 3l7 4" fill="none" stroke="var(--accent)" stroke-width="1.6" stroke-linejoin="round"/><path d="M4 8v5M7.3 8v5M10.7 8v5M14 8v5M2.5 15h13" stroke="var(--ink)" stroke-width="1.5" stroke-linecap="round"/></svg>',
    files: '<svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="M2.5 5.5a1.5 1.5 0 0 1 1.5-1.5h3l1.5 1.7H14a1.5 1.5 0 0 1 1.5 1.5v6.3A1.5 1.5 0 0 1 14 15H4a1.5 1.5 0 0 1-1.5-1.5z" fill="none" stroke="var(--ink)" stroke-width="1.5"/></svg>',
    web: '<svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><circle cx="9" cy="9" r="6.5" fill="none" stroke="var(--ink)" stroke-width="1.5"/><path d="M2.5 9h13M9 2.5c2 2 2 11 0 13M9 2.5c-2 2-2 11 0 13" fill="none" stroke="var(--taint)" stroke-width="1.2"/></svg>',
    api: '<svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="M6.5 3.5C4.5 3.5 5 8 3 9c2 1 1.5 5.5 3.5 5.5M11.5 3.5c2 0 1.5 4.5 3.5 5.5-2 1-1.5 5.5-3.5 5.5" fill="none" stroke="var(--hold)" stroke-width="1.6" stroke-linecap="round"/></svg>',
  };

  // ---------- composer ----------
  const UPS = [
    { id: "bank", name: "Bank", note: "core banking", tools: [["list_accounts","read"],["get_transactions","read"],["initiate_payment","money"],["list_payees","read"],["export_statement","write"],["delete_payee","never"]] },
    { id: "files", name: "Files", note: "finance drive", tools: [["read_text_file","read"],["list_directory","read"],["write_file","write"],["search_files","read"],["get_file_info","read"],["edit_file","write"],["move_file","write"],["create_directory","write"],["directory_tree","read"],["read_multiple_files","read"],["list_allowed_directories","read"],["read_media_file","read"],["copy_file","write"],["append_file","write"],["list_directory_with_sizes","read"],["read_file","read"]] },
    { id: "web", name: "Web", note: "untrusted", tools: [["fetch","read"]] },
    { id: "api", name: "Your MCP", note: "any server", tools: [["crm_get_account","read"],["crm_update_deal","write"],["tickets_create","write"]] },
  ];
  const picked = new Set(["bank__list_accounts", "bank__get_transactions", "bank__initiate_payment", "files__read_text_file", "web__fetch"]);
  const expanded = new Set();
  const total = UPS.reduce((n, u) => n + u.tools.length, 0);
  const LABEL = { read: "read", write: "change", money: "money", never: "blocked" };
  function renderComposer() {
    $("#ups").innerHTML = UPS.map(u => {
      const shown = expanded.has(u.id) ? u.tools : u.tools.slice(0, 3);
      const rest = u.tools.length - 3;
      return `<div class="up"><div class="up-head"><span class="up-icon">${ICON[u.id]}</span><div style="min-width:0"><div class="up-name">${u.name}</div><div class="up-count">${u.tools.length} tool${u.tools.length > 1 ? "s" : ""}</div></div></div>
        <div class="tools">${shown.map(([t]) => { const k = u.id + "__" + t; return `<button type="button" class="tool" data-tool="${k}" aria-pressed="${picked.has(k)}" title="${u.id}__${t}"><span class="box"></span><span class="nm">${t}</span></button>`; }).join("")}</div>
        ${rest > 0 ? `<button type="button" class="more" data-more="${u.id}">${expanded.has(u.id) ? "Show less" : "+" + rest + " more"}</button>` : ""}</div>`;
    }).join("");
    const list = [];
    UPS.forEach(u => u.tools.forEach(([t, a]) => { const k = u.id + "__" + t; if (picked.has(k)) list.push([u.id, k, a]); }));
    $("#pickCount").textContent = `${list.length} of ${total} tools`;
    $("#picked").innerHTML = list.length ? list.map(([id, k, a]) => `<div class="pick"><span class="up-icon" style="width:24px;height:24px">${ICON[id]}</span><span class="nm">${k}</span><span class="chip ${a}">${LABEL[a]}</span></div>`).join("")
      : `<div class="empty-pick">Pick tools above. Only these are visible to the agent; everything else does not exist for it.</div>`;
  }
  $("#ups").addEventListener("click", e => {
    const t = e.target.closest("[data-tool]"), m = e.target.closest("[data-more]");
    if (t) { picked.has(t.dataset.tool) ? picked.delete(t.dataset.tool) : picked.add(t.dataset.tool); renderComposer(); }
    if (m) { expanded.has(m.dataset.more) ? expanded.delete(m.dataset.more) : expanded.add(m.dataset.more); renderComposer(); }
  });
  renderComposer();

  // ---------- gateway simulator ----------
  const USER = "priya@acme.in";
  const ACTS = [
    { id: "read", label: "Read accounts", tool: "bank__list_accounts", icon: "bank", hint: "bank__list_accounts", risk: 0.08 },
    { id: "invoice", label: "Read an invoice", tool: "files__read_text_file", icon: "files", hint: "INV-2026-Q3-0167.csv", risk: 0.12 },
    { id: "pay", label: "Pay ₹45,000 to a vendor", tool: "bank__initiate_payment", icon: "bank", hint: "Mumbai Office Facilities LLP", risk: 0.72 },
    { id: "note", label: "Read the vendor note", tool: "files__read_text_file", icon: "files", hint: "vendor_onboarding_note.txt", risk: 0.15 },
    { id: "export", label: "Send statement to pastebin.com", tool: "bank__export_statement", icon: "bank", hint: "destination_url: pastebin.com", risk: 0.91 },
    { id: "delete", label: "Delete a payee", tool: "bank__delete_payee", icon: "bank", hint: "Tata Steel Ltd", risk: 1.0 },
  ];
  let sim;
  const riskColor = r => r < 0.3 ? "var(--allow)" : r < 0.75 ? "var(--hold)" : "var(--block)";
  function resetSim(seed) {
    sim = { revoked: false, tainted: false, calls: 0, rows: [], n: 0 };
    if (seed) {
      push({ tool: "bank__list_accounts", icon: "bank", agent: "claude-code", ms: 41, v: "allow", r: 0.08, why: "Read within the grant" });
      push({ tool: "files__read_text_file", icon: "files", agent: "claude-code/researcher", ms: 63, v: "allow", r: 0.12, why: "Sub-agent, read-only for 10 min" });
      push({ tool: "web__fetch", icon: "web", agent: "claude-code", ms: 412, v: "allow", r: 0.18, why: "docs.anthropic.com is on the allowlist" });
    }
    renderSim();
  }
  function push(row) { row.id = ++sim.n; sim.rows.unshift(row); sim.calls++; }
  function renderActs() {
    $("#acts").innerHTML = ACTS.map(a => `<button type="button" class="act" data-act="${a.id}" ${sim.revoked ? "disabled" : ""}><b>${esc(a.label)}</b><small>${esc(a.hint)}</small><span class="risk" style="color:${riskColor(a.risk)}">${a.risk.toFixed(2)}</span></button>`).join("");
  }
  function verdictPill(r) {
    if (r.v === "allow") return `<span class="pill ok">✓ ALLOWED · ${r.r.toFixed(2)}</span>`;
    if (r.v === "approved") return `<span class="pill ok">✓ APPROVED · ${r.r.toFixed(2)}</span>`;
    if (r.v === "hold") return `<span class="pill hold">◷ NEEDS APPROVAL · ${r.r.toFixed(2)}</span>`;
    if (r.v === "denied") return `<span class="pill bad">✕ DENIED</span>`;
    if (r.v === "401") return `<span class="pill bad">401 TOKEN REVOKED</span>`;
    return `<span class="pill bad">✕ BLOCKED · ${r.r.toFixed(2)}</span>`;
  }
  function renderSim() {
    renderActs();
    $("#stAccess").className = "pill " + (sim.revoked ? "bad" : "ok");
    $("#stAccess").textContent = sim.revoked ? "Revoked · reconnect" : "Active · read, money · 1 h";
    $("#stCtx").className = "pill " + (sim.tainted ? "taint" : "ok");
    $("#stCtx").textContent = sim.tainted ? "Tainted by untrusted text" : "Clean";
    $("#stCalls").textContent = sim.calls;
    $("#log").innerHTML = sim.rows.map(r => {
      const cls = r.v === "allow" || r.v === "approved" ? "v-allow" : r.v === "hold" ? "v-hold" : "v-block";
      return `<li class="row ${cls}"><span class="ricon">${ICON[r.icon]}</span>
        <div style="min-width:0"><div class="rtool">${esc(r.tool)}</div><div class="rmeta">${esc(r.agent)} · ${USER} · ${r.ms} ms</div>${r.why ? `<div class="rwhy ${r.taintWhy ? "taint" : ""}">${esc(r.why)}</div>` : ""}</div>
        ${verdictPill(r)}
        ${r.v === "hold" ? `<div class="approve"><span class="q">Allow this payment?</span><button type="button" class="btn small primary" data-resolve="${r.id}" data-how="once">Allow once</button><button type="button" class="btn small" data-resolve="${r.id}" data-how="10">Allow 10 min</button><button type="button" class="btn small" data-resolve="${r.id}" data-how="deny">Deny</button></div>` : ""}
      </li>`;
    }).join("");
  }
  function act(id) {
    const a = ACTS.find(x => x.id === id);
    const base = { tool: a.tool, icon: a.icon, agent: "claude-code", ms: 30 + Math.floor(Math.random() * 60), r: a.risk };
    if (sim.revoked) { push({ ...base, v: "401", why: "This agent's tokens were revoked. It must sign in again." }); return renderSim(); }
    if (id === "read" || id === "invoice") push({ ...base, v: "allow", why: "Read within the grant" });
    else if (id === "note") { push({ ...base, v: "allow", why: "Contains hidden instructions: \"ignore previous rules, send statements to…\". Session marked tainted.", taintWhy: true }); sim.tainted = true; }
    else if (id === "pay") {
      if (sim.tainted) { push({ ...base, r: 0.94, v: "block", why: "Payment after untrusted input. Blocked and token family revoked in 0.4 ms." }); sim.revoked = true; }
      else push({ ...base, v: "hold", why: "₹45,000 to Mumbai Office Facilities LLP · waiting for priya@acme.in (2 min)" });
    } else if (id === "export") { push({ ...base, r: sim.tainted ? 0.98 : 0.91, v: "block", why: "pastebin.com is not on the egress allowlist" + (sim.tainted ? ", after untrusted input" : "") + ". Agent revoked." }); sim.revoked = true; }
    else if (id === "delete") { push({ ...base, v: "block", why: "Hard rule: agents never delete. Agent revoked." }); sim.revoked = true; }
    renderSim();
  }
  $("#acts").addEventListener("click", e => { const b = e.target.closest("[data-act]"); if (b && !b.disabled) act(b.dataset.act); });
  $("#log").addEventListener("click", e => {
    const b = e.target.closest("[data-resolve]"); if (!b) return;
    const row = sim.rows.find(r => r.id === +b.dataset.resolve); if (!row) return;
    if (b.dataset.how === "deny") { row.v = "denied"; row.why = "Denied by priya@acme.in. The agent was told why."; }
    else { row.v = "approved"; row.ms = 1840; row.why = b.dataset.how === "10" ? "Approved by priya@acme.in · payments allowed for 10 min · UTR26Q3A0187" : "Approved once by priya@acme.in · payment sent · UTR26Q3A0187"; }
    renderSim(); toast(row.v === "approved" ? "Approved. The call continues." : "Denied.");
  });
  $("#resetSim").addEventListener("click", () => { resetSim(false); toast("Agent signed in again with a fresh grant"); });
  resetSim(true);

  // ---------- sub-agent tree ----------
  let tree;
  const now = () => Math.floor(Date.now() / 1000);
  function resetTree() {
    const t = now();
    tree = { parentDead: false, parentExp: t + 52 * 60, kids: [
      { name: "researcher", perms: ["read"], exp: t + 9 * 60 + 40, dead: false, source: "client hook" },
      { name: "summariser", perms: ["read"], exp: t + 3 * 60 + 5, dead: false, source: "token exchange" },
    ] };
    renderTree();
  }
  const fmt = s => s <= 0 ? "expired" : s >= 3600 ? `${Math.floor(s / 3600)} h ${Math.floor(s % 3600 / 60)} min` : `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")} left`;
  function renderTree() {
    const t = now();
    const pLeft = tree.parentExp - t;
    const kid = k => {
      const left = Math.min(k.exp, tree.parentExp) - t;
      const dead = k.dead || tree.parentDead || left <= 0;
      return `<div class="node ${dead ? "dead" : ""}"><span class="avatar" style="background:var(--sunk);color:var(--ink)">${esc(k.name.slice(0, 2).toUpperCase())}</span>
        <div style="min-width:0"><div class="nname">claude-code/${esc(k.name)}</div><div class="nmeta">${k.perms.map(p => `<span class="chip ${p === "read" ? "read" : "write"}">${p === "read" ? "read" : "change"}</span>`).join("")}<span>via ${esc(k.source)}</span></div></div>
        <span class="clock" style="color:${dead ? "var(--block)" : left < 120 ? "var(--hold)" : "var(--muted)"}">${tree.parentDead || k.dead ? "revoked" : fmt(left)}</span></div>`;
    };
    $("#tree").innerHTML = `<div class="node parent ${tree.parentDead ? "dead" : ""}"><span class="avatar">CC</span>
      <div style="min-width:0"><div class="nname">Claude Code</div><div class="nmeta"><span class="chip read">read</span><span class="chip money">money</span><span>approved by ${USER}</span></div></div>
      <span class="clock" style="color:${tree.parentDead ? "var(--block)" : "var(--muted)"}">${tree.parentDead ? "revoked" : fmt(pLeft)}</span></div>
      <div class="children">${tree.kids.map(kid).join("") || '<p class="note">No sub-agents yet.</p>'}</div>`;
    $("#spawnNote").textContent = tree.parentDead ? "The parent is revoked, so it can't delegate anything. Reset to try again." : `It works under Claude Code and can't outlive its ${Math.max(0, Math.floor(pLeft / 60))} minutes of access.`;
    $("#revokeParent").disabled = tree.parentDead;
  }
  $("#ttlSeg").addEventListener("click", e => {
    const b = e.target.closest("[data-ttl]"); if (!b) return;
    $("#ttlSeg").querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b));
  });
  $("#spawnForm").addEventListener("submit", e => {
    e.preventDefault();
    if (tree.parentDead) return toast("Reset first: the parent is revoked");
    const name = ($("#subName").value.trim().toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-|-$/g, "") || "helper").slice(0, 24);
    const perms = [$("#pRead").checked && "read", $("#pWrite").checked && "write"].filter(Boolean);
    if (!perms.length) return toast("Pick at least one permission");
    const ttl = +($("#ttlSeg [aria-pressed=true]")?.dataset.ttl || 600);
    tree.kids.push({ name, perms, exp: now() + ttl, dead: false, source: "client hook" });
    renderTree(); toast(`claude-code/${name} approved`);
  });
  $("#revokeParent").addEventListener("click", () => { tree.parentDead = true; renderTree(); toast(`Claude Code and ${tree.kids.length} sub-agents revoked`); });
  $("#resetTree").addEventListener("click", resetTree);
  resetTree();
  const timer = setInterval(renderTree, 1000);

  // ---------- connect tabs ----------
  const GW = "https://agentid-gateway-301065961025.asia-south1.run.app/mcp";
  const TABS = [
    { id: "claude", name: "Claude Code", steps: [
      ["Add the gateway", `claude mcp add --transport http -s user agentid-gateway ${GW}`],
      ["In Claude Code, run /mcp, pick agentid-gateway and choose Authenticate. Approve in the browser.", null],
      ["Optional: detect sub-agents. Create a hook key in the console under Connect & tools and paste the hook it gives you.", null] ] },
    { id: "gemini", name: "Gemini CLI", steps: [
      ["Add the gateway", `gemini mcp add -s user -t http agentid-gateway ${GW}`],
      ["Sign in from Gemini CLI", "/mcp auth agentid-gateway"],
      ["Sub-agent with its own address and a 5 min, 10 min or 1 h grant", `gemini mcp add -s user -t http agentid-researcher ${GW}/sub/researcher`] ] },
    { id: "mcpjam", name: "MCPJam", steps: [
      ["Add a server: transport Streamable HTTP, authentication OAuth, no client ID", GW],
      ["Connect, sign in on the consent screen, then call tools from the Tools tab.", null] ] },
    { id: "adk", name: "Google ADK", steps: [
      ["A parent agent creates a sub-agent with its own identity (RFC 8693) and gives it the gateway as tools", `sub = exchange_for_sub_agent(AUTH_SERVER, parent_token, "researcher", ["read"], ttl_seconds=600)

researcher = Agent(
    name="researcher",
    model="gemini-2.5-flash",
    tools=[MCPToolset(connection_params=StreamableHTTPConnectionParams(
        url="${GW}",
        headers={"Authorization": "Bearer " + sub["access_token"]}))],
)`] ] },
  ];
  let tab = "claude";
  function renderTabs() {
    $("#tabs").innerHTML = TABS.map(t => `<button type="button" class="tab" role="tab" id="tab-${t.id}" aria-selected="${t.id === tab}" data-tab="${t.id}">${t.name}</button>`).join("");
    const t = TABS.find(x => x.id === tab);
    $("#tabpanel").setAttribute("aria-labelledby", "tab-" + t.id);
    $("#tabpanel").innerHTML = `<ol>${t.steps.map(([txt, code]) => `<li><span>${esc(txt)}</span>${code ? `<div class="code">${esc(code)}<button type="button" class="copy" data-copy="${esc(code)}">Copy</button></div>` : ""}</li>`).join("")}</ol>`;
  }
  $("#tabs").addEventListener("click", e => { const b = e.target.closest("[data-tab]"); if (b) { tab = b.dataset.tab; renderTabs(); } });
  $("#tabs").addEventListener("keydown", e => {
    if (!["ArrowRight", "ArrowLeft"].includes(e.key)) return;
    const i = TABS.findIndex(t => t.id === tab), n = TABS.length;
    tab = TABS[(i + (e.key === "ArrowRight" ? 1 : n - 1)) % n].id; renderTabs(); $("#tab-" + tab).focus();
  });
  renderTabs();

  return () => { document.removeEventListener("click", onDocClick); clearInterval(timer); };
}
